h2,p,dl{margin:0}h2{font-size:14px}.secondary{font-size:12px;color:var(--sub);overflow-wrap:anywhere}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-2)}.toolbar h2,.profile-actions #profile-current{flex:1;min-width:0;overflow-wrap:anywhere}label{font-weight:600}
button,input,textarea,select{font:inherit;border:1px solid var(--input-border);border-radius:var(--radius-control);color:var(--ink);background:var(--paper);min-height:36px;padding:var(--space-2)}button{cursor:pointer}button:hover:enabled{background:var(--bg)}button:disabled{opacity:.55;cursor:default}button.primary{background:var(--brand);color:#fff;border-color:var(--brand)}button.primary:hover:enabled{filter:brightness(.92);background:var(--brand)}button.danger{color:var(--negative)}input,textarea,select{width:100%;min-width:0}textarea{resize:vertical;font:12px/1.6 ui-monospace,monospace}.actions{margin-top:var(--space-1)}.actions .primary{flex:1}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}.status-grid{display:grid;grid-template-columns:auto minmax(0,1fr);gap:var(--space-1) var(--space-3)}dt{color:var(--sub)}dd{margin:0;overflow-wrap:anywhere}pre{margin:0;background:var(--bg);border:1px solid var(--line);border-radius:var(--radius-control);padding:var(--space-3);white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;font-size:12px}
