details{min-width:0;border:1px solid var(--line);border-radius:var(--radius-control);padding:0 var(--space-3)}details[open]{padding-bottom:var(--space-3)}details[open]>*+*{margin-top:var(--space-2)}details[open]>label{display:block}summary{cursor:pointer;font-weight:600;min-height:44px;align-content:center;overflow-wrap:anywhere}summary .secondary{display:block;font-weight:400;padding-left:var(--space-4)}details.flat{border:0;border-radius:0;padding:0}details.flat>summary{min-height:36px}details.flat[open]{padding-bottom:var(--space-2)}
.field{display:grid;gap:var(--space-2);min-width:0}.field-pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--space-2)}input[type=checkbox]{width:auto;min-height:0;margin-right:var(--space-2)}
.profile-list{display:flex;flex-wrap:wrap;gap:var(--space-2)}.profile-list:empty{display:none}.profile-list button{border-color:var(--line);overflow-wrap:anywhere;max-width:100%;text-align:left}.profile-list [aria-pressed=true]{border-color:var(--brand);box-shadow:inset 0 0 0 1px var(--brand);color:var(--brand);background:var(--bg)}.profile-actions{font-size:12px;color:var(--sub)}
.run-summary{font-weight:600;overflow-wrap:anywhere}.run-summary[data-tone=success]{color:var(--positive)}.run-summary[data-tone=error]{color:var(--negative)}.empty-state{color:var(--sub);padding:var(--space-3);background:var(--bg);border-radius:var(--radius-control)}#record-summary{color:var(--sub);font-size:12px}
/* Keep long values readable in their own scroll region, never squeeze 7–11 fields into the panel. */
.table-scroll{max-width:100%;overflow:auto;max-height:360px;border:1px solid var(--line);border-radius:var(--radius-control)}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th,td{border-bottom:1px solid var(--line);padding:var(--space-2);vertical-align:top;min-width:120px;max-width:280px;overflow-wrap:anywhere}th{background:var(--bg);position:sticky;top:0;z-index:1}tbody tr:nth-child(even){background:var(--bg)}
@media(prefers-color-scheme:dark){:root{--ink:#e9eef7;--sub:#b3c1d3;--line:#374457;--brand:#3566ba;--paper:#151c28;--bg:#101722;--input-border:#6d809b;--negative:#ff9ea6;--positive:#a1f3cc;--focus:#9dc1ff}.profile-list [aria-pressed=true]{color:var(--focus)}}
